<script setup lang="ts">import AdminLayout from '@/Layouts/AdminLayout.vue';import{Head,router}from'@inertiajs/vue3';import{reactive}from'vue';const props=defineProps<{groups:any,filters:any}>();const form=reactive({search:props.filters.search||''});const filter=()=>router.get(route('admin.groups.index'),form,{preserveState:true});const act=(id:number,action:string)=>{const reason=action==='suspend'?prompt('Reason for suspending this group:'):'';if(action==='suspend'&&!reason)return;router.post(route('admin.groups.moderate',id),{action,reason})};</script>
<template><Head title="Groups"/><AdminLayout><h1 class="text-2xl font-bold">Groups</h1><form class="mt-5 flex gap-3" @submit.prevent="filter"><input v-model="form.search" class="rounded border px-3 py-2" placeholder="Search group name"><button class="rounded bg-slate-900 px-4 py-2 text-white">Search</button></form><div class="mt-5 overflow-x-auto rounded-xl border bg-white"><table class="w-full text-sm"><thead class="bg-slate-50 text-left text-slate-500"><tr><th class="p-4">Group</th><th>Owner</th><th>Members</th><th>Messages</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="group in groups.data" :key="group.id" class="border-t"><td class="p-4"><b>{{group.name}}</b><div class="text-slate-500">{{new Date(group.created_at).toLocaleDateString()}}</div></td><td>{{group.creator?.name}}</td><td>{{group.members_count}}</td><td>{{group.messages_count}}</td><td class="capitalize">{{group.status}}</td><td><button v-if="group.status==='active'" class="text-rose-700" @click="act(group.id,'suspend')">Suspend</button><button v-else class="text-cyan-700" @click="act(group.id,'restore')">Restore</button></td></tr><tr v-if="!groups.data.length"><td colspan="6" class="p-8 text-center text-slate-500">No groups found.</td></tr></tbody></table></div></AdminLayout></template>
